#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int r,c;scanf("%d %d",&r,&c);
vector<long long>dp(c,1);
for(int i=1;i<r;++i)for(int j=1;j<c;++j)dp[j]+=dp[j-1];
printf("%lld\n",dp[c-1]);return 0;}

